// Function to unlock scroll on modal close
function unlockScroll() {
  document.body.classList.remove("modal-open");
  document.body.style.overflow = ""; // Reset overflow
}

// Call functions to create the modal and navbar
createNavbar();
createModal();

document.getElementById("TryNowButton").addEventListener("click", function (event) {
  event.preventDefault(); // Prevent form submission initially

  // Get all required input fields
  const nameInput = document.getElementById("Name");
  const emailInput = document.getElementById("Email");
  const organisationInput = document.getElementById("Organisation");
  const domainInput = document.getElementById("Domain");
  const communityReachInput = document.getElementById("Community_Reach");

  // Get validation message elements
  const nameValidation = document.getElementById("name-validation");
  const emailValidation = document.getElementById("email-validation");
  const orgValidation = document.getElementById("org-validation");
  const domainValidation = document.querySelector('#Domain + span[id="org-validation"]');

  // Reset previous validation messages
  [nameValidation, emailValidation, orgValidation, domainValidation].forEach(el => {
    if (el) el.style.display = "none";
  });

  // Validation flag
  let isValid = true;

  // Validate Name
  if (!nameInput.value.trim()) {
    nameValidation.style.display = "block";
    isValid = false;
  }

  // Validate Email with a simple regex
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailInput.value.trim() || !emailRegex.test(emailInput.value.trim())) {
    emailValidation.textContent = "Please enter a valid email address";
    emailValidation.style.display = "block";
    isValid = false;
  }

  // Validate Organisation
  if (!organisationInput.value.trim()) {
    orgValidation.textContent = "Organisation is required";
    orgValidation.style.display = "block";
    isValid = false;
  }

  // Validate Domain
  if (!domainInput.value.trim()) {
    domainValidation.textContent = "Area/domain of expertise is required";
    domainValidation.style.display = "block";
    isValid = false;
  }

  // Validate Community Reach
  const communityReachToggle = document.getElementById("CommunityReach");
  if (!communityReachInput.value.trim()) {
    communityReachToggle.style.color = "red";
    isValid = false;
  } else {
    communityReachToggle.style.color = ""; // Reset color
  }

  // If all validations pass, submit the form
  if (isValid) {
    const formData = new FormData(document.getElementById("tryNowForm"));

    fetch(
      "https://script.google.com/macros/s/AKfycby2qEXdIZellDgwgXXwiS_M7D7R8SsDhnTZm3DWLfo_CCZlY6YcnR7nTVybhhF-fh6xew/exec",
      {
        method: "POST",
        body: formData,
      }
    )
    .then((response) => response.json())
    .then((data) => {
      // Show success message
      document.getElementById("responseMessage").textContent =
        "Form submitted successfully!";

      if (data.result === "success") {
        const thankYouMessage = document.getElementById("thanks-yous-try");
        if (thankYouMessage) {
          thankYouMessage.style.display = "block"; // Show thank you message

          const trynowclose = document.getElementById("closetry");
          setTimeout(() => {
            if (trynowclose) {
              trynowclose.click(); // Trigger the close button
            } else {
              console.error("'Close' button element not found.");
            }
          }, 3000);
        } else {
          console.error("Thank-you message element not found.");
        }
      }
    })
    .catch((error) => {
      // Handle errors
      document.getElementById("responseMessage").textContent =
        "An error occurred. Please try again.";
      console.error("Error:", error);
    });
  }
});

// Function to unlock scroll on modal close
function unlockScroll() {
  document.body.classList.remove("modal-open");
  document.body.style.overflow = ""; // Reset overflow
}

function setupDropdown() {
  const dropdownToggle = document.getElementById("CommunityReach");
  const dropdownMenu = document.getElementById("customDropdownMenu");
  const dropdownItems = document.querySelectorAll(".custom-dropdown-item");
  const hiddenInput = document.getElementById("Community_Reach");

  // Toggle dropdown menu
  dropdownToggle.addEventListener("click", (e) => {
    e.stopPropagation();
    dropdownMenu.classList.toggle("show");
  });

  // Handle item selection
  dropdownItems.forEach((item) => {
    item.addEventListener("click", (e) => {
      e.stopPropagation();
      const selectedValue = item.textContent;
      dropdownToggle.querySelector("span").textContent = selectedValue;
      hiddenInput.value = selectedValue; // Update the hidden input value
      dropdownMenu.classList.remove("show");
    });
  });

  // Close dropdown when clicking outside
  document.addEventListener("click", () => {
    dropdownMenu.classList.remove("show");
  });
}
